using System;
using LastRail.Run;
using Newtonsoft.Json.Linq;
namespace LastRail.Battle {
 public sealed partial class BDirectAttackBasicLoop {
  public BDirectAttackBasicLoopResult MoveOrdinaryOperator(string id,string actor,int slot,JArray localPoint,string geometryHash)=>Commit(new JObject{["kind"]="ORDINARY_MOVE",["eventId"]=id,["actorId"]=actor,["slot"]=slot,["pointMm"]=localPoint?.DeepClone(),["geometryHash"]=geometryHash});
  public static BDirectAttackBasicLoop CreateOrdinaryGeometryRuntime(BDirectAttackBasicLoopBinding binding,BBoardingEventsNodeSnapshot source,BOrdinaryGeometryBinding geometry,int capacity,bool namedSource=false)=>CreateSpatialGeometryRuntime(binding,source,new BLegacySpatialGeometry(geometry),capacity,namedSource);
  internal static BDirectAttackBasicLoop CreateSpatialGeometryRuntime(BDirectAttackBasicLoopBinding binding,BBoardingEventsNodeSnapshot source,BOrdinarySpatialGeometry geometry,int capacity,bool namedSource=false){BuffWire.Need(geometry!=null&&geometry.Input!=null&&geometry.Input.OriginalHash==binding.Composition.Attack.OriginalHash,"b_ordinary_geometry_binding");var owner=namedSource?CreateInterceptSourceRuntime(binding,source,geometry.Paths(),capacity):CreateGunnerInterceptLocalRuntime(binding,source,geometry.Paths(),capacity);owner.boarding.Spatial=new BOrdinarySpatialOwner(geometry,source.OriginalSource);owner.boarding.Spatial.ObserveOperators(owner.session);return owner;}
  public JObject ObserveOrdinaryGeometry(string source,string target,long expectedTick,long expectedRevision,string expectedGeometryHash){BuffWire.Need(boarding?.Spatial!=null,"b_ordinary_geometry_source_missing");var state=boarding.Spatial.Capture();BuffWire.Need(expectedTick==Tick&&expectedRevision==(long)state["revision"]&&expectedGeometryHash==(string)state["geometryHash"],"b_ordinary_geometry_observation_version");BuffWire.Need(boarding.TryGeometry(source,target,Tick,out var frame),"b_ordinary_geometry_entity_source_missing");return frame;}
  public static BDirectAttackBasicLoop RestoreOrdinaryGeometryRuntime(JObject cache,string hash,BDirectAttackBasicLoopBinding binding,BBoardingEventsNodeSnapshot source,BOrdinaryGeometryBinding geometry,int capacity,bool namedSource=false){BuffWire.Need(cache!=null&&BDirectAttackInput.Digest(cache)==hash,"b_ordinary_geometry_cache_hash");var owner=CreateOrdinaryGeometryRuntime(binding,source,geometry,capacity,namedSource);foreach(var c in BuffWire.Array(cache["commands"],0,capacity))owner.Commit(BuffWire.Object(c));BuffWire.Need(JToken.DeepEquals(cache,owner.Capture()),"b_ordinary_geometry_cache_replay");return owner;}
 }
}
